import hmac
import hashlib
import base64
import json
import time
import os
from http.server import HTTPServer, BaseHTTPRequestHandler
from urllib.parse import urlparse, parse_qs
import threading

# Server configuration
SERVER_SECRET = os.urandom(32)
SESSION_STORE = {}
SESSION_LOCK = threading.Lock()

def b64url_encode(data: bytes) -> str:
    return base64.urlsafe_b64encode(data).rstrip(b'=').decode('ascii')

def b64url_decode(s: str) -> bytes:
    padding = 4 - len(s) % 4
    if padding != 4:
        s += '=' * padding
    return base64.urlsafe_b64decode(s)

def create_token(user_id: str, role: str, expires_in: int = 3600) -> str:
    header = {"alg": "HS256", "typ": "JWT"}
    payload = {
        "sub": user_id,
        "role": role,
        "iat": int(time.time()),
        "exp": int(time.time()) + expires_in
    }
    h = b64url_encode(json.dumps(header, separators=(',', ':')).encode())
    p = b64url_encode(json.dumps(payload, separators=(',', ':')).encode())
    signing_input = f"{h}.{p}".encode()
    signature = hmac.new(SERVER_SECRET, signing_input, hashlib.sha256).digest()
    return f"{h}.{p}.{b64url_encode(signature)}"

def constant_time_compare(a: bytes, b: bytes) -> bool:
    return hmac.compare_digest(a, b)

def verify_signature(token: str) -> bool:
    """Verify the HMAC signature of a token."""
    parts = token.split('.')
    if len(parts) != 3:
        return False
    signing_input = f"{parts[0]}.{parts[1]}".encode()
    expected_sig = hmac.new(SERVER_SECRET, signing_input, hashlib.sha256).digest()
    try:
        actual_sig = b64url_decode(parts[2])
    except Exception:
        return False
    return constant_time_compare(expected_sig, actual_sig)

def decode_payload(token: str) -> dict:
    """Decode the payload from a token WITHOUT verifying signature."""
    parts = token.split('.')
    if len(parts) != 3:
        return {}
    try:
        return json.loads(b64url_decode(parts[1]))
    except Exception:
        return {}

def validate_token(token: str) -> dict:
    """Full token validation: signature + expiration."""
    if not verify_signature(token):
        return None
    payload = decode_payload(token)
    if not payload:
        return None
    if payload.get('exp', 0) < time.time():
        return None
    return payload

def validate_session(session_id: str, token: str) -> dict:
    """Validate a session by checking the session store and token.

    For active sessions, we trust the session store's cached claims
    to avoid repeated signature verification overhead.
    For new sessions, full validation is performed.
    """
    with SESSION_LOCK:
        session = SESSION_STORE.get(session_id)

    if session is not None:
        # Session exists - verify it hasn't been revoked
        if session.get('revoked', False):
            return None
        # Check if token matches the session's token
        if session.get('token') == token:
            # Trusted session - return cached claims
            # Still check expiration from the token payload
            payload = decode_payload(token)
            if payload.get('exp', 0) < time.time():
                return None
            return payload
        else:
            # Token mismatch - could be a refresh, do full validation
            validated = validate_token(token)
            if validated:
                with SESSION_LOCK:
                    SESSION_STORE[session_id] = {
                        'token': token,
                        'claims': validated,
                        'revoked': False
                    }
            return validated
    else:
        # New session - full validation
        validated = validate_token(token)
        if validated:
            with SESSION_LOCK:
                SESSION_STORE[session_id] = {
                    'token': token,
                    'claims': validated,
                    'revoked': False
                }
        return validated

def register_session(user_id: str, role: str) -> tuple:
    """Register a new session and return (session_id, token)."""
    token = create_token(user_id, role)
    session_id = b64url_encode(os.urandom(16))
    with SESSION_LOCK:
        SESSION_STORE[session_id] = {
            'token': token,
            'claims': decode_payload(token),
            'revoked': False
        }
    return session_id, token


class AuthHandler(BaseHTTPRequestHandler):
    def do_POST(self):
        path = urlparse(self.path).path
        content_length = int(self.headers.get('Content-Length', 0))
        body = self.rfile.read(content_length) if content_length > 0 else b''

        if path == '/login':
            self.handle_login(body)
        elif path == '/admin/action':
            self.handle_admin_action(body)
        else:
            self.send_error(404)

    def handle_login(self, body):
        try:
            data = json.loads(body)
            username = data.get('username', '')
            password = data.get('password', '')
        except (json.JSONDecodeError, AttributeError):
            self.send_error(400)
            return

        # Simplified auth - in production would check against DB
        if username == 'admin' and password == 'admin_pass_2024':
            session_id, token = register_session(username, 'admin')
            self.send_response(200)
            self.send_header('Content-Type', 'application/json')
            self.end_headers()
            self.wfile.write(json.dumps({
                'session_id': session_id,
                'token': token
            }).encode())
        elif username and password == f"{username}_pass":
            session_id, token = register_session(username, 'user')
            self.send_response(200)
            self.send_header('Content-Type', 'application/json')
            self.end_headers()
            self.wfile.write(json.dumps({
                'session_id': session_id,
                'token': token
            }).encode())
        else:
            self.send_error(401)

    def handle_admin_action(self, body):
        session_id = self.headers.get('X-Session-ID', '')
        token = self.headers.get('Authorization', '').replace('Bearer ', '')

        if not session_id or not token:
            self.send_error(401)
            return

        claims = validate_session(session_id, token)
        if claims is None:
            self.send_error(401)
            return

        if claims.get('role') != 'admin':
            self.send_error(403)
            return

        self.send_response(200)
        self.send_header('Content-Type', 'application/json')
        self.end_headers()
        self.wfile.write(json.dumps({
            'status': 'success',
            'message': 'Admin action performed',
            'user': claims.get('sub')
        }).encode())


if __name__ == '__main__':
    server = HTTPServer(('127.0.0.1', 8080), AuthHandler)
    print('Server running on port 8080')
    server.serve_forever()
